def main(shots: int = SHOTS):
    name = str(getattr(backend, "name", backend))
    if "qpu" in name.lower():
        raise SystemExit("Refusing to run the ladder on real hardware from this script.")
    out = {}
    for key, text in QASM.items():
        qc = qasm2.loads(text, custom_instructions=qasm2.LEGACY_CUSTOM_INSTRUCTIONS)
        try:
            job = backend.run(qc, shots=shots)
        except Exception:
            job = backend.run(transpile(qc, backend), shots=shots)
        for _ in range(720):
            st = str(job.status())
            if "DONE" in st:
                break
            if "ERROR" in st or "CANCEL" in st:
                raise RuntimeError(st)
            time.sleep(3)
        out[key] = job.result().get_counts()
        print(key, "done", flush=True)
    print("RESULT_JSON_START")
    print(json.dumps(dict(backend=name, shots=shots, counts=out)))
    print("RESULT_JSON_END")
